#!/bin/sh
# Owner-approved list of the exact read-only check scripts the no-approval check key may run.
# GENERATED by ops/vps/make-trust-checks.sh from ops/vps/check-operations.txt; do not edit by hand.
#
#   apply   write /etc/nexus-ops/trusted-checks (root-owned, read-only for others) with the list
#           below, replacing the previous list. Needs the owner's approval: it is not itself a check.
#   show    print the list installed on the server now
#
# The runner accepts a check-key request only if "<operation> <script SHA-256>" is in that file
# AND the operation and argument are on its built-in read-only list. Changes nothing else.
set -u
umask 022
F=${NEXUS_OPS_TEST_TRUSTED:-/etc/nexus-ops/trusted-checks}
case "${1:-}" in apply|show) ;; *) echo "usage: trust-checks.sh apply|show"; exit 64 ;; esac
if [ "$1" = show ]; then
    if [ -f "$F" ]; then echo "trusted now ($F):"; sed 's/^/  /' "$F"; else echo "nothing trusted yet ($F does not exist)"; fi
    exit 0
fi
tmp="$F.new.$$"
cat > "$tmp" <<'LIST'
hello c0f492a335cf4e1dc2511fea3650e29b565b841c2feea902061a3b42d2963bbc
ops-log e111995ec8f90c6c3990e3bdde2e0abc9763d5ce9e913b97d514aa1055549eda
p1b-stop-staging eccb9c461ef15782d408b3cf38111ab71eb9684ff64ce1cbc2ab1a41d86b549f
pa-backup 8313acc31f3739f283f8d3049c3c2dde6081e990e3e8eb3f48832595af0b6da6
staging-backup 7e06d1b32a43d0e46913a0e43c96b94f0ee32b7b2f170873bfa7ff0899364803
staging-config-check 06c8f15e0321318ece117e939176ce6275d9bf7e5846a05bdd37902c959f2573
staging-inventory 27bafb11455c9bce15d6a6bbd0eaca4571bdb93bc381cda4e8eb06e1d3ecfec8
staging-pa-off-check b339d5b0c9ea17bbcb96d14ee724b7100ff175db8dda4bbb28ef15e0174ce3e9
staging-pa-off-stop 066f5f46bc0fa95c92a925575ebe55e641ac094be860b825ea7b002929614321
LIST
[ "$(id -u)" = 0 ] && chown 0:0 "$tmp"
chmod 644 "$tmp"
mv -f "$tmp" "$F"
echo "trusted for the check key ($F):"
sed 's/^/  /' "$F"
echo "Only these exact scripts can run without approval. Nothing else was changed."
